enum ReadFailure: Error { case missing, invalid }

func readLabel(_ text: String?) throws(ReadFailure) -> String {
    guard let text else { throw .missing }
    guard !text.isEmpty else { throw .invalid }
    return text
}

func readLater(_ text: String?) async throws(ReadFailure) -> String {
    try readLabel(text)
}

func caller() async {
    do {
        _ = try await readLater(nil)
    } catch {
        let failure: ReadFailure = error
        switch failure {
        case .missing: break
        case .invalid: break
        }
    }
}

