enum ReadFailure: Error, Sendable {
    case missing
    case invalid
}

enum ReadOutcome: Sendable {
    case completed(Result<String, ReadFailure>)
    case cancelled
}

func startCancellableRead(
    _ read: @escaping @Sendable () async -> ReadOutcome
) -> Task<ReadOutcome, Never> {
    Task { await read() }
}

func constructingAndAwaitingCaller() async {
    let cancellation = startCancellableRead {
        precondition(!Task.isCancelled)
        return .cancelled
    }
    switch await cancellation.value {
    case .cancelled:
        print("cancelled outcome retained while Task.isCancelled == false")
    case .completed:
        preconditionFailure("Expected explicit cancellation outcome")
    }

    let failure = startCancellableRead {
        .completed(.failure(.invalid))
    }
    switch await failure.value {
    case .completed(.failure(.invalid)):
        print("ReadFailure.invalid retained")
    default:
        preconditionFailure("Expected retained domain failure")
    }
}

@main
struct Probe {
    static func main() async {
        await constructingAndAwaitingCaller()
    }
}

